query AutomaticAgent2Batches($blocks:[numeric!]!,$router:String!,$registry:String!){
 SyncStatus(where:{chainId:{_eq:10143},router:{_eq:$router},registry:{_eq:$registry}}){id chainId router registry blockNumber}
 Agent(where:{chainId:{_eq:10143},registry:{_eq:$registry},agentId:{_eq:2}}){agentId owner shardsCreated tasksCompleted}
 MerkleBatch(where:{chainId:{_eq:10143},router:{_eq:$router},blockNumber:{_in:$blocks}},order_by:{blockNumber:asc}){batchId blockNumber blockHash root leafCount status committedRoot committedLeafCount commitmentTx commitmentBlock}
 BatchCommitment(where:{chainId:{_eq:10143},router:{_eq:$router},fromBlock:{_in:$blocks}},order_by:{fromBlock:asc}){id chainId router batchId root leafCount fromBlock toBlock verified transactionHash}
}
